```json
{
  "root_causes": [
    {
      "service": "product-catalog",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, count(*) c FROM normal_traces WHERE service_name='product-catalog' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name='product-catalog'",
          "claim": "product-catalog emits about 300 spans in the normal period but only 2 in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) c FROM abnormal_traces WHERE span_name LIKE '%ProductCatalogService/%' GROUP BY 1,2,3,4 ORDER BY 1,2,4",
          "claim": "In the abnormal period every ProductCatalog call from checkout, frontend and recommendation is an Error span; almost no server spans remain."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, metric, min(value) vmin, max(value) vmax, count(*) n FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'product-catalog%' AND metric='k8s.container.restarts' GROUP BY 1,2",
          "claim": "product-catalog pod restart counter is 1 in the abnormal window, while it was 0 throughout the normal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "product-catalog",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) c, quantile_cont(duration/1e6,0.5) p50ms FROM abnormal_traces WHERE service_name='checkout' AND span_name LIKE '%GetProduct%' GROUP BY 1,2,3",
          "claim": "checkout's GetProduct client calls to product-catalog all return Error in about 0.1 ms, while none succeed."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "recommendation",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) c FROM abnormal_traces WHERE service_name='recommendation' GROUP BY 1,2,3",
          "claim": "recommendation's ListProducts calls to product-catalog are all Error (29), and its get_product_list spans are Error too."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) c FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('grpc.oteldemo.CheckoutService/PlaceOrder','POST /api/checkout') GROUP BY 1,2,3",
          "claim": "frontend's PlaceOrder client calls and POST /api/checkout requests fail with Error/500 in the abnormal period."
        }
      ]
    },
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) c FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE '%Recommendation%' GROUP BY 1,2,3",
          "claim": "frontend's ListRecommendations client calls fail (Error) for all 29 requests in the abnormal period."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) err_share FROM normal_traces WHERE service_name='frontend-proxy' UNION ALL SELECT 'abnormal', avg(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END) FROM abnormal_traces WHERE service_name='frontend-proxy'",
          "claim": "frontend-proxy error share rises from about 0.06 in the normal period to about 0.60 in the abnormal period."
        }
      ]
    }
  ]
}
```

